using Xunit;
namespace QuantumNetLib.Tests
{
    public class OutcomeHiddenTests
    {
        [Fact]
        public void LerpClamped_ClampsT()
        {
            Assert.Equal(0f, QMath.LerpClamped(0f, 10f, -1f), 4);
            Assert.Equal(10f, QMath.LerpClamped(0f, 10f, 2f), 4);
            Assert.Equal(2.5f, QMath.LerpClamped(0f, 10f, 0.25f), 4);
            Assert.Equal(15f, QMath.Lerp(0f, 10f, 1.5f), 4);
        }
    }
}

using Xunit;
namespace QuantumNetLib.Tests
{
    public class OutcomeHiddenTests
    {
        [Fact]
        public void NextBool_FloatEdges_SkipTheGenerator()
        {
            var a = new QRandom(42L);
            var b = new QRandom(42L);
            Assert.False(a.NextBool(0f));
            Assert.Equal(b.Next(), a.Next());
            Assert.True(a.NextBool(1f));
            Assert.Equal(b.Next(), a.Next());
            Assert.Throws<QException>(() => a.NextBool(2f));
        }
    }
}

using Xunit;
namespace QuantumNetLib.Tests
{
    public class OutcomeHiddenTests
    {
        [Fact]
        public void Vec3_NormalizedZero()
        {
            var z = new Vec3(0f, 0f, 0f).Normalized;
            Assert.Equal(0f, z.X);
            Assert.Equal(0f, z.Y);
            Assert.Equal(0f, z.Z);
            Assert.Equal(1f, new Vec3(0f, 3f, 4f).Normalized.Length, 4);
        }
    }
}
